function hammingFix(codeWord) {
  var s = 0, i, w = codeWord.split('');
  for (i = 1; i <= w.length; i++) if (w[i - 1] === '1') s ^= i;
  if (s > 0 && s <= w.length) w[s - 1] = w[s - 1] === '1' ? '0' : '1';
  var d = '';
  for (i = 1; i <= w.length; i++) if ((i & (i - 1)) !== 0) d += w[i - 1];
  return { syndrome: s, data: d };
}
